const OP_CLIP = V2dBu((18-1.5)/Math.SQRT2);         // LM833 on ±18 V (inferred swing)
const LEG_CLIP = V2dBu((RAIL-VSAT)/Math.SQRT2);     // one output leg
const CARDMAX = 30;                                 // spec maximum, M8205B; = two legs of ±20 V less margin
const D = {};
function reset(){ Object.assign(D, { ver:'M8205B', board:'14-310', inDbu:4, f:1000, sens:null, lf:0.38, hf:0.6, cm:-30, load:600, shorted:0, frame:'MF82/10', inserted:true, loop:false, sel:null, rsel:null, ev:[] }); D.sens=detent(); }
const V = ()=>VER[D.ver];
function detent(){ const v=VER[D.ver||'M8205B']; return (0-v.gmin)/(v.gmax-v.gmin); }
const gainDb = ()=> V().gmin + (V().gmax-V().gmin)*D.sens;
function cmrr(){ const e=Math.hypot(D.lf-0.5, (D.hf-0.5)*0.4); return clamp(100 - 160*e, 52, 100); }
function chain(){
  const v=V(), g=gainDb(), inOn=D.inserted;
  const sIn = inOn? D.inDbu : -140;
  const s1 = sIn, s2 = s1 + g;
  const card = s2;                                          // balanced: + leg and − leg each carry half (−6 dB), the pair adds back to the stage-2 level
  // output-stage current: every output draws V/(2Rs+RL); a shorted output draws V/(2Rs)
  const Vpk = Math.SQRT2*dBu2V(Math.min(card, CARDMAX)), Rload=D.load;
  const nOk = D.shorted? 7 : 8, Ieach = Vpk/(2*v.rs+Rload), Ish = D.shorted? Vpk/(2*v.rs) : 0;
  const Itot = nOk*Ieach + Ish, limited = Itot > ILIM;
  const k = limited? ILIM/Itot : 1;
  const legMax = CARDMAX;                                    // +30 at the card (both versions); the M8205's +24 is after its 600 Ω build-out
  const atCard = Math.min(card + dB(k), legMax);
  const atLoad = atCard + dB(Rload/(Rload+2*v.rs));
  const Irms = (atCard>-100? dBu2V(atCard)/(2*v.rs+Rload):0), pRs = Irms*Irms*v.rs, pSh = D.shorted? Math.pow(dBu2V(atCard)/(2*v.rs),2)*v.rs : 0;
  const cmr = cmrr(), hum = D.cm - cmr + g + 6.02, noise = -95 + Math.max(0,g);
  const stages = [
    {name:'Input (TB8205P IN ±)', db:sIn, g:null, note: inOn? `${D.f} Hz tone, 30 kΩ balanced` : 'card not in the frame'},
    {name:'U1A balanced input', db:s1, g:0, max:OP_CLIP, note:'LM833, R1/R2 16K2 1 %, CMR trims R9 (LF DIF) and C4 (HF DIF)'},
    {name:'SENSITIVITY U1B/U2A', db:s2, g, max:OP_CLIP, note:'R14A/R14B 5K-V multi-turn; detent = unity'},
    {name:'Output pair (U3+/U4−)', db:card, g:0, max:CARDMAX, note:'NE5534 + TIP29B/TIP30B per leg; U4 inverts through R35 4K75'},
    {name:'At the load ('+D.load+' Ω)', db:atLoad, g:dB(Rload/(Rload+2*v.rs)), note:`through 2 × ${v.rs} Ω`},
  ];
  return { g, s1, s2, card, atCard, atLoad, limited, Itot, Ieach, Ish, Irms, pRs, pSh, cmr, hum, noise, stages, clip: s1>OP_CLIP||s2>OP_CLIP||card>CARDMAX+0.01||limited };
}

/* ---------------- actions ---------------- */
const A = {
  setSens(v, log){ D.sens=v; D.ev.push({t:SIM.t,name:'SENS '+gainDb().toFixed(1)+' dB'}); if(log) act('SENSITIVITY (R14A/B) turned', tr=>{ const c=chain(); tr(`R14A/R14B 5K-V dual multi-turn: ${D.ver} gain range ${V().gmin} … +${V().gmax} dB → now ${c.g>=0?'+':''}${c.g.toFixed(1)} dB${Math.abs(c.g)<0.3?' (at the detent: unity)':''}`); tr(`U1B → U2A carries ${fmtDb(c.s2)}; the output pair delivers ${fmtDb(c.card)} across + and −`); if(c.clip) tr('<b style="color:var(--bad)">Clipping</b>: '+(c.s2>OP_CLIP?'U2A runs out of ±18 V swing':c.limited?'the output current limit (Q1/Q4 2N4401 across R42/R43 2.2 Ω) is folding back':'the output legs reach the ±22 V rails')); }); },
  setLf(v, log){ D.lf=v; if(log) act('LF DIF trim (R9 5K) adjusted', tr=>{ tr(`R9 balances the resistive arms of the U1A difference amplifier (R5/R10 8K25 1 %, R6/R7 75 1 %)`); tr(`CMRR now ≈ ${cmrr().toFixed(0)} dB (spec: greater than 80 dB); hum at the output ${fmtDb(chain().hum)}`); }); },
  setHf(v, log){ D.hf=v; if(log) act('HF DIF trim (C4 2–18 pF) adjusted', tr=>{ tr('C4 trims the capacitive balance against C3 15P, so the rejection holds up to 20 kHz'); tr(`CMRR ≈ ${cmrr().toFixed(0)} dB`); }); },
  ver(v){ act('Version '+v, tr=>{ D.ver=v; D.sens=detent(); tr(`${v}: ${VER[v].z} outputs, build-outs ${VER[v].rLab}`); tr(`Gain range ${VER[v].gmin} … +${VER[v].gmax} dB (spec table); maximum output +${VER[v].max} dBm`); }); },
  load(v){ act('Load on every output: '+v+' Ω', tr=>{ D.load=v; const c=chain(); tr(`Each output: ${fmtDb(c.atLoad)} across ${v} Ω (build-out loss ${(c.atLoad-c.atCard).toFixed(2)} dB)`); }); },
  short(n){ act(n? 'Short OUTPUT '+n : 'Remove the short', tr=>{ D.shorted=n; const c=chain(); if(!n){ tr('All eight outputs loaded normally'); return; } tr(`OUTPUT ${n} ± tied together: the leg pair sees only 2 × ${V().rs} Ω → ${(c.Ish*1000).toFixed(0)} mA peak from that output`); tr(`Total output-stage current ${(c.Itot*1000).toFixed(0)} mA peak vs the ≈ ${(ILIM*1000).toFixed(0)} mA limit ${'('}${'0.65 V / 2.2 Ω'}${') '}${inf}`); tr(c.limited? `<b style="color:var(--bad)">Current limit</b>: every other output drops by ${(-dB(ILIM/c.Itot)).toFixed(1)} dB — the isolation spec (> 60 dB) holds only while the stage is not limiting` : `Not limiting: the other seven outputs move by less than 0.01 dB (each has its own build-out resistors)`); tr(`Power in each build-out of the shorted output: ${c.pSh.toFixed(2)} W (part rated ${V().pw} W)`); }); },
  input(v){ D.inDbu=v; SIM.refresh(); },
  freq(v){ act('Test tone '+v+' Hz', tr=>{ D.f=v; tr(`Frequency response ± 0.1 dB, 20 Hz – 20 kHz (spec). Slew needed per leg at max level: ${(2*Math.PI*v*Math.SQRT2*dBu2V(V().max-6.02)/1e6).toFixed(2)} V/µs (NE5534: 13 V/µs typical ${inf})`); }); },
  cm(v){ D.cm=v; SIM.refresh(); },
  insert(){ act(D.inserted?'Pull the card out':'Slide the card into the frame', tr=>{ D.inserted=!D.inserted; if(D.inserted){ tr(D.frame==='MF82/4'? 'MF82/4 frame: pins 1 and A to the left, handle ident reads left to right' : `${D.frame} frame: pins 1 and A at the top, handle letters read from the top down`); tr('P1 (30-way edge, 0.156 in) mates with the backplane; +22 V on 15/S, common 14/R, −22 V on 13/P'); } else tr('Outputs fall silent; the TB8205P on the rear stays wired'); }); },
  frame(v){ act('Frame '+v, tr=>{ D.frame=v; tr(v==='MF82/4'?'Horizontal card: pins 1 and A to the left':'Vertical card: pins 1 and A at the top'); }); },
  part(r){ act('Part '+r, tr=>{ D.sel=r; const p=BRD[D.board].parts.find(q=>q.ref===r); tr(`${r}: ${p&&p.v?p.v:'(no value in the PCB file)'} · footprint ${p?p.pat:'?'} · at ${p?p.x.toFixed(2)+', '+p.y.toFixed(2)+' in from the front-top corner':''}`); const role=ROLE[r.replace(/[AB]$/,'')]; if(role) tr(role); }); },
  rrow(i){ act('Rear terminal '+REAR.rows[i][0], tr=>{ D.rsel=i; const s=rearSig(REAR.rows[i][0]); tr(s||'Label on the TB8205P artwork'); if(/LOOP/.test(REAR.rows[i][0])){ D.loop=!D.loop; tr(D.loop?'Passive input loop wired on to the next card: the input sees 30 kΩ ∥ 30 kΩ = 15 kΩ — still bridging':'Loop open'); } }); },
  reset(){ act('Start over', tr=>{ reset(); tr('M8205B, +4 dBu in, sensitivity at the detent'); }); },
};
const ROLE = { U1:'U1 LM833N: U1A balanced input difference amplifier, U1B first gain stage (SENSITIVITY)', U2:'U2 LM833N: U2A second gain stage (R14B), U2B spare (follower)', U3:'U3 NE5534N: drives the + output leg (Q5 TIP29B / Q6 TIP30B)', U4:'U4 NE5534N: drives the − leg, inverting through R35 4K75', R9:'R9 5K: LF DIF common-mode trim', C4:'C4 2–18 pF: HF DIF common-mode trim', R14:'R14A/R14B 5K-V: the SENSITIVITY control', LK1:'LK1 / LK2: links between P1 input pins and R1/R2 (cut to isolate the input)', LK2:'LK1 / LK2: input links', R42:'R42 2.2 Ω 1 W: emitter resistor and current-sense for Q4 2N4401', Q5:'Q5 TIP29B / Q3 TIP30B: output transistors', Q3:'output transistor', P1:'P1 EDGE30/156: the 30-way edge connector to the backplane' };
function rearSig(lab){ const c=chain(); if(/^IN|INPUT/.test(lab)) return `${lab}: ${fmtDb(D.inDbu)} into 30 kΩ balanced (P1 pins 1 and A)`; const m=lab.match(/OUT\s*(\d)\s*([+-])/); if(m) return `OUTPUT ${m[1]} ${m[2]}: ${fmtDb(c.atLoad-6.02)} each leg, ${fmtDb(c.atLoad)} balanced across ${D.load} Ω${+m[1]===D.shorted?' — SHORTED':''}`; if(/SHIELD/.test(lab)) return 'Input shield → P1 B (common, input shield)'; if(/GND/.test(lab)) return 'Ground'; return null; }

/* ---------------- drawings ---------------- */
function boardCtl(){ const B=BRD[D.board]; return [
  {k:'sens', label:'SENSITIVITY R14A/R14B (front edge)', short:'SENS', kind:'multi', x:0.375, y:0.505, get:()=>D.sens, set:(v,l)=>A.setSens(v,l)},
  {k:'lf', label:'R9 LF DIF (common-mode trim)', short:'LF DIF', kind:'trim', x:3.775, y:0.405, get:()=>D.lf, set:(v,l)=>A.setLf(v,l)},
  {k:'hf', label:'C4 HF DIF (2–18 pF trimmer)', short:'HF DIF', kind:'trim', x:3.35, y:0.605, ly:1.0, get:()=>D.hf, set:(v,l)=>A.setHf(v,l)} ]; }
function panelHTML(){ const B=BRD[D.board]; B.ctl=boardCtl(); const c=chain();
  const ext=`<rect x="${(B.ox+0.0)*100}" y="${(B.oy)*100}" width="${10.6*100}" height="${2.73*100}" fill="none" stroke="${c.clip?'var(--bad)':'transparent'}" stroke-width="3"/>`;
  return card('The card — '+D.ver+' on PCB '+(D.board==='14-310'?'14-310':'14-310 (M8205B.PCB)'), boardSVG(B,{sel:D.sel, extra:ext})+controlsHTML())
   + `<div class="grid2">${card('Front edge', handleSVG(D.ver, `<g class="hnd" style="cursor:pointer"><title>Click: slide the card ${D.inserted?'out of':'into'} the frame</title><rect x="10" y="80" width="60" height="100" fill="transparent"/></g><text x="80" y="140" font-size="11" fill="${D.inserted?'var(--accent)':'var(--warn)'}">${D.inserted?'in the frame':'pulled out'}</text>`))}${card('Rear module TB8205P', rearSVG(Object.assign(REAR,{sig:rearSig, img:D.ver==='M8205B'?'m8205-rear-tb8205p-b.png':'m8205-rear-tb8205p.png'}),{sel:D.rsel}) + `<div class="small muted">From the 8200 Series rear-module guide (2012|45). Click a terminal label.</div>`)}</div>`; }
function controlsHTML(){ return `<div class="small" style="display:flex;flex-wrap:wrap;gap:8px 14px;margin-top:8px;align-items:center">
  <label>Version <select data-c="ver">${Object.keys(VER).map(k=>`<option ${k===D.ver?'selected':''}>${k}</option>`).join('')}</select></label>
  <label>Input <input type="range" data-c="in" min="-22" max="20" step="1" value="${D.inDbu}"> <span class="mono">${fmtDb(D.inDbu)}</span></label>
  <label>Tone <select data-c="f">${[100,1000,10000,20000].map(v=>`<option value="${v}" ${v===D.f?'selected':''}>${v>=1000?v/1000+' kHz':v+' Hz'}</option>`).join('')}</select></label>
  <label>Load <select data-c="load">${[600,10000,100000].map(v=>`<option value="${v}" ${v===D.load?'selected':''}>${v>=1000?v/1000+' k':v} Ω</option>`).join('')}</select></label>
  <label>Short an output <select data-c="short"><option value="0">none</option>${[1,2,3,4,5,6,7,8].map(n=>`<option value="${n}" ${n===D.shorted?'selected':''}>OUTPUT ${n}</option>`).join('')}</select></label>
  <label>Common-mode hum <input type="range" data-c="cm" min="-60" max="0" value="${D.cm}"> <span class="mono">${fmtDb(D.cm)}</span></label>
  <label>Board file <select data-c="board"><option ${D.board==='14-310'?'selected':''}>14-310</option><option value="M8205B" ${D.board==='M8205B'?'selected':''}>M8205B.PCB</option></select></label>
  <label>Frame <select data-c="frame">${['MF82/10','MF82/12','MF82/4'].map(v=>`<option ${v===D.frame?'selected':''}>${v}</option>`).join('')}</select></label>
  <button data-c="reset">Start over</button></div>`; }
function bind(root){ const B=BRD[D.board]; bindBoard(root,B,r=>A.part(r));
  root.querySelectorAll('.rrow').forEach(g=>g.onclick=()=>A.rrow(+g.dataset.i)); root.querySelectorAll('.hnd').forEach(g=>g.onclick=()=>A.insert());
  root.querySelectorAll('[data-c]').forEach(e=>{ const c=e.dataset.c;
    if(c==='reset') e.onclick=()=>A.reset();
    else if(c==='in') e.oninput=()=>A.input(+e.value); else if(c==='cm') e.oninput=()=>A.cm(+e.value);
    else e.onchange=()=>{ const v=e.value; if(c==='ver') A.ver(v); if(c==='f') A.freq(+v); if(c==='load') A.load(+v); if(c==='short') A.short(+v); if(c==='board'){ D.board=v; SIM.refresh(); } if(c==='frame') A.frame(v); }; }); }
function stateHTML(){ const c=chain(), v=V(); return `<table class="kv"><tr><th>Version</th><td>${D.ver}: ${v.z}, gain ${v.gmin} … +${v.gmax} dB</td></tr><tr><th>Gain</th><td class="mono">${c.g>=0?'+':''}${c.g.toFixed(1)} dB${Math.abs(c.g)<0.3?' (detent)':''}</td></tr><tr><th>Card output</th><td class="mono">${fmtDb(c.atCard)}${c.limited?' · current-limited':''}</td></tr><tr><th>At each load</th><td class="mono">${fmtDb(c.atLoad)} across ${D.load} Ω</td></tr><tr><th>Output current</th><td class="mono">${(c.Itot*1000).toFixed(0)} mA pk total (limit ≈ ${(ILIM*1000).toFixed(0)} mA ${inf})</td></tr><tr><th>CMRR / hum</th><td class="mono">${c.cmr.toFixed(0)} dB · hum ${fmtDb(c.hum)}</td></tr><tr><th>Noise floor</th><td class="mono">${fmtDb(c.noise)} (spec −95 dBu at unity)</td></tr></table>`; }
function lanes(){ const c=chain(), f=D.f, v=V();
  const atStage=(d,clip)=>t=>sineV(t,d,f,clip);
  return [
    waveLane('Input at TB8205P (IN±)', 44, atStage(D.inserted?D.inDbu:-140), {f, col:SIM.css('--ink2')}),
    waveLane('U1A out ('+fmtDb(c.s1)+')', 44, atStage(c.s1,OP_CLIP), {f, clip:OP_CLIP}),
    waveLane('U2A out after SENSITIVITY', 44, atStage(c.s2,OP_CLIP), {f, clip:OP_CLIP}),
    waveLane('+ leg (U3, Q5/Q6)', 40, t=>sineV(t,Math.min(c.atCard,c.card)-6.02,f,LEG_CLIP), {f, clip:LEG_CLIP, col:SIM.css('--accent2')}),
    waveLane('− leg (U4, Q2/Q3)', 40, t=>-sineV(t,Math.min(c.atCard,c.card)-6.02,f,LEG_CLIP), {f, clip:LEG_CLIP, col:SIM.css('--warn')}),
    waveLane('OUTPUT '+(D.shorted===1?2:1)+' across '+D.load+' Ω', 46, t=>sineV(t,c.atLoad,f,CARDMAX), {f, clip:CARDMAX, note:()=>fmtDb(c.atLoad)}),
    waveLane('Hum at the output (60 Hz, ×'+(c.hum<-60?'1000':'1')+')', 34, t=>sineV(t,c.hum+(c.hum<-60?60:0),60), {f:60, col:SIM.css('--bad')}),
    eventLane('Your adjustments', ()=>D.ev),
  ]; }
function secondHTML(){ const c=chain(), v=V(); const Pd = 2*(RAIL*c.Itot/Math.PI) ; return `<table class="kv">
 <tr><th>Tone cycles</th><td class="mono">${D.f.toLocaleString()} in 1 s</td></tr>
 <tr><th>Card output</th><td class="mono">${fmtDb(c.atCard)} (${(Math.SQRT2*dBu2V(c.atCard)).toFixed(2)} V peak across the pair)</td></tr>
 <tr><th>Per output</th><td class="mono">${(c.Irms*1000).toFixed(1)} mA rms · ${(c.pRs*1000).toFixed(1)} mW in each ${v.rs} Ω build-out</td></tr>
 <tr><th>8 outputs</th><td class="mono">${(c.Itot*1000).toFixed(0)} mA peak from each leg</td></tr>
 <tr><th>Output transistors</th><td class="mono">≈ ${Pd.toFixed(2)} W average per leg (class B, ±22 V ${inf})</td></tr>
 <tr><th>Slew needed</th><td class="mono">${(2*Math.PI*D.f*Math.SQRT2*dBu2V(c.atCard-6.02)/1e6).toFixed(2)} V/µs per leg</td></tr>
 <tr><th>Hum / noise</th><td class="mono">${fmtDb(c.hum)} / ${fmtDb(c.noise)}</td></tr>
 <tr><th>Supply</th><td class="mono">±22 V in on P1 15/S, 13/P; Q7 2N6718 / Q8 2N6730 pass transistors make ±18 V for the op-amps; 40 mA idling (spec)</td></tr></table>
 <p class="small">There is no clock and no code: the second is a thousand identical cycles of the test tone. What changes is what you do — every trim move appears as an event, and the level, clipping and current follow at once.</p>`; }

/* ---------------- tutorial (from m8205.pdf) ---------------- */
const lessons = [
  {title:'The card', auto:true, check:()=>true, body:`<p>The ${'M8205'} and M8205B are single-channel, low-noise distribution amplifiers: <b>one balanced input, eight balanced outputs</b>. The M8205 has 600 Ω outputs, the M8205B 60 Ω. A multi-turn <b>SENSITIVITY</b> pot sets the gain; its detent is unity (m8205.pdf).</p><p>The card has no connectors of its own: the TB8205P (or TB8205, ST8200) on the rear of the frame carries the terminals.</p>`},
  {title:'1 · Install it the right way up', check:()=>D.inserted&&D.frame!=='MF82/4', hint:'Pick MF82/10 in “Frame” and click the handle if the card is out.', body:`<p>In an MF82/10 or MF82/12 frame, pins 1 and A go at the top and the letters on the handle read from the top down. In an MF82/4, pins 1 and A go to the left.</p><p><b>Goal:</b> the card in an MF82/10 or MF82/12.</p>`},
  {title:'2 · Pick the version for the plant', check:()=>D.ver==='M8205'&&D.load===600, hint:'Version → M8205, Load → 600 Ω.', body:`<p>A 600 Ω matched installation wants the <b>M8205</b> (301 Ω per leg). Into 600 Ω it loses 6 dB: that is why its spec lists +24 dBm maximum where the M8205B lists +30.</p><p><b>Goal:</b> M8205 driving 600 Ω loads.</p>`},
  {title:'3 · Unity gain at the detent', check:()=>Math.abs(gainDb())<0.3&&D.inDbu===4, hint:'Input +4 dBu; click the blue SENS knob at the front edge until the gain reads 0.0 dB.', body:`<p>Feed +4 dBu and set SENSITIVITY to its detent: the output equals the input.</p><p><b>Goal:</b> +4 dBu in, gain 0 dB.</p>`},
  {title:'4 · Find the ceiling', check:()=>chain().clip, hint:'Raise the input to +14 or turn SENS up until a stage turns red.', body:`<p>The input range on the schematic is −22 to +14 dBm. Push the level until a stage clips and look at the Timeline: the dashed red lines are each stage's swing limit.</p><p><b>Goal:</b> make it clip.</p>`},
  {title:'5 · Null the common-mode hum', check:()=>D.cm>=-20&&cmrr()>=80, hint:'Common-mode hum to −20 dBu or more, then step R9 LF DIF (and C4 HF DIF) towards the middle.', body:`<p>Hum that arrives equally on IN+ and IN− should cancel. R9 (LF DIF) and C4 (HF DIF) balance the U1A difference amplifier.</p><p><b>Goal:</b> −20 dBu of common-mode hum and CMRR at or above the 80 dB spec.</p>`},
  {title:'6 · Short one output', check:()=>D.shorted>0, hint:'“Short an output” → OUTPUT 3. Try both versions.', body:`<p>Each output has its own pair of build-out resistors, so a short on one barely moves the others — until the output stage reaches its current limit. The M8205B (30 Ω) reaches it much sooner than the M8205 (301 Ω).</p><p><b>Goal:</b> short an output and read the trace.</p>`},
  {title:'Done', auto:true, check:()=>true, body:`<p>See <b>Findings</b> for what the files say that the manual does not.</p>`},
];

