const blocks = { w:780, h:300, note:'Redrawn from M8205B8.DWG. The live level is shown in the corner of each block.', nodes:{
  tb:{x:10,y:110,w:110,h:56,t:'TB8205P',s:['IN ±, SH','(+ passive loop)'],lv:()=>fmtDb(D.inDbu),info:'Rear termination: pluggable screw terminals for IN +, IN −, shield and OUT 1–8 ±. The input reaches P1 pins 1 and A through links LK2/LK1.'},
  in:{x:150,y:110,w:130,h:56,t:'U1A input',s:['LM833 diff amp','R9 LF / C4 HF DIF'],lv:()=>fmtDb(chain().s1),info:()=>`Balanced difference amplifier: R1/R2 16K2 1 % input, CR1–CR4 1N4148 clamps, R3/R4 100K. CMRR ≈ ${cmrr().toFixed(0)} dB.`},
  sens:{x:310,y:110,w:140,h:56,t:'SENSITIVITY',s:['U1B → U2A','R14A/B 5K-V'],lv:()=>fmtDb(chain().s2),info:()=>`Two LM833 stages with the dual multi-turn pot. Gain now ${gainDb().toFixed(1)} dB.`},
  p:{x:490,y:40,w:140,h:56,t:'+ leg U3',s:['NE5534 → Q5/Q6','TIP29B/TIP30B'],info:'Non-inverting output leg. 2N4401 Q4 with R42 2.2 Ω limits the current.'},
  n:{x:490,y:180,w:140,h:56,t:'− leg U4',s:['NE5534 (inv, R35)','Q2/Q3'],info:'Inverting leg, driven from the + leg through R35 4K75 1 %.'},
  o:{x:660,y:110,w:110,h:56,t:'8 × build-out',s:['2 × '+'Rs per output','OUT 1–8 ±'],lv:()=>fmtDb(chain().atLoad),info:()=>`Each output: ${V().rLab}. + side on P1 D,E,F,H,J,K,L,M; − side on 4–11.`},
  pw:{x:150,y:230,w:300,h:56,t:'Power',s:['±22 V on P1 15/S, 13/P → Q7/Q8 → ±18 V','40 mA idling (spec)'],info:'Q7 2N6718 and Q8 2N6730 with R54–R59 make the ±18 V op-amp rails; the output transistors run from ±22 V.'} },
  edges:[['tb','in','P1 1/A'],['in','sens'],['sens','p'],['sens','n'],['p','o'],['n','o'],['pw','sens','±18 V']] };

/* ---------------- schematics ---------------- */
function pinSheet(){ const pins=[['1','IN (via LK2, R1)'],['A','IN (via LK1, R2)'],['B','COMMON (input shield)'],['D…M','OUTPUT 1–8 (+ leg, R44–R51)'],['4…11','OUTPUT 1–8 (− leg, R27–R34)'],['15 / S','+22 V'],['14 / R','COMMON (ground)'],['13 / P','−22 V']];
  return `<svg viewBox="0 0 640 ${pins.length*30+60}" style="width:100%;max-width:640px;background:var(--lane);border:1px solid var(--line);border-radius:8px"><text x="20" y="26" font-size="14" font-weight="700" fill="var(--ink)">P1 — 30-way edge (EDGE30/156), as labelled on M8205B8.DWG</text>${pins.map((p,i)=>`<rect x="20" y="${44+i*30}" width="90" height="22" rx="3" fill="#d4af37"/><text x="65" y="${59+i*30}" text-anchor="middle" font-size="12" font-weight="700" fill="#000">${p[0]}</text><line x1="110" y1="${55+i*30}" x2="170" y2="${55+i*30}" stroke="var(--ink)"/><text x="180" y="${59+i*30}" font-size="12" fill="var(--ink)">${p[1]}</text>`).join('')}</svg>`; }
const sheets = [
  {name:'M8205B8.DWG — schematic (REV 8)', J:SCH, note:'Every line, symbol and label is read from the AutoCAD R12 file and drawn at its own coordinates (symbol blocks expanded). Click a label to see its neighbours (value, pin numbers).', hl:()=>D.sel?[D.sel]:[]},
  {name:'P1 pin-out', svg:pinSheet, note:'From the P1 labels on M8205B8.DWG (1, A, B, D–M, 4–11, 13/P, 14/R, 15/S).'},
];

/* ---------------- signal path ---------------- */
function softHTML(){ const c=chain(), v=V(); const outs=[1,2,3,4,5,6,7,8].map(n=>{ const sh=n===D.shorted; const lvl=sh?-140:c.atLoad; const i=sh? c.Ish/Math.SQRT2 : c.Irms; return `<tr><td>OUTPUT ${n}</td><td class="mono">D…M / 4…11</td><td class="mono" style="color:${sh?'var(--bad)':'inherit'}">${sh?'shorted':fmtDb(lvl)}</td><td class="mono">${(i*1000).toFixed(1)} mA</td><td class="mono">${(i*i*v.rs*1000).toFixed(1)} mW / ${v.pw} W</td></tr>`; }).join('');
  return `<div class="grid2">${card('Signal path, stage by stage', stageTable(c.stages)+'<p class="small muted">Ceilings: op-amps on ±18 V and output legs on ±22 V are '+inf+' from the rail values on the schematic; the +'+v.max+' dBm maximum is the spec.</p>')}${card('Level diagram', levelSVG(c.stages))}</div>
   <div class="grid2">${card('Fan-out to the eight outputs', `<table class="kv"><tr><th>Output</th><th>P1</th><th>Level at load</th><th>Current rms</th><th>Build-out power</th></tr>${outs}</table><p class="small">Output isolation is specified at > 60 dB. A short is isolated by the build-outs until the leg reaches its current limit (${(ILIM*1000).toFixed(0)} mA peak ${inf}).</p>`)}
   ${card('Version maths', `<p class="small">V<sub>load</sub> = V<sub>card</sub> × R<sub>L</sub> / (R<sub>L</sub> + 2R<sub>s</sub>).</p><table class="kv"><tr><th></th><th>M8205</th><th>M8205B</th></tr><tr><td>R<sub>s</sub> per leg</td><td>301 Ω ½ W</td><td>30 Ω 1 W</td></tr><tr><td>Into 600 Ω</td><td class="mono">${dB(600/1202).toFixed(2)} dB</td><td class="mono">${dB(600/660).toFixed(2)} dB</td></tr><tr><td>Into 10 kΩ</td><td class="mono">${dB(1e4/10602).toFixed(2)} dB</td><td class="mono">${dB(1e4/10060).toFixed(2)} dB</td></tr><tr><td>Max out (spec)</td><td>+24 dBm</td><td>+30 dBm</td></tr></table><p class="small">+30 at the card minus the 6 dB lost in a matched 600 Ω build-out gives the M8205's +24 dBm: the two specs are the same amplifier.</p>`)}</div>`; }

const findings = [
  `<b>The manual contradicts itself on gain.</b> The General text of <span class="mono">m8205.pdf</span> / <span class="mono">M8205MAN.WPD</span> says both versions adjust −14 to +18 dB; its own specification table gives the M8205 −20 to +12 dB and only the M8205B −14 to +18 dB. The simulator follows the table.`,
  `<b>A typo names the wrong card.</b> The M8205 spec table lists “Maximum Output Level … M8204B: +30 dBm”. There is no M8204B in the analog range; it means the M8205B (+30 dBm).`,
  `<b>+24 vs +30 dBm is one amplifier.</b> Both versions share the same output stage. The M8205's 301 Ω-per-leg build-out halves the voltage into 600 Ω (−6 dB), which turns +30 into the +24 dBm in the spec.`,
  `<b>The OrCAD file is misnamed and mistyped.</b> <span class="mono">PCB/M8205.DSN</span> carries the internal name “M8205B.DSN” (JUNE 14,1997) and the title “MONO AUDIO DISTRIBUTION AMPLIFIER -14-265 ISS 3 PCB”, with the note “30R FOR M8205B, AND 300R FOR THE <b>M8025</b>”.`,
  `<b>Three PCBs for one product.</b> 14-310 (Tango, 1995|28, silk “M8205”), the same layout re-saved as M8205B.PCB (silk “M8205B, ISS 1 PCB”, placement only — no copper), and later the M8204's 14-265 (<span class="mono">m8205-14-265iss6.sch</span>, 2001|34; <span class="mono">M8205B.STN</span> in the M8204 Gerber folder; the BOM tool's 14-265 ISSUE 8 “RoHS M8204A/M8205/M8205B AUDIO DA”).`,
  `<b>Schematic and DSN disagree on the PCB.</b> M8205B8.DWG (REV 8) is titled “M8205B, ISS 1 PCB” (the 14-310 layout) while the DSN says “14-265 ISS 3 PCB”.`,
  `<b>Misfiled DRC log.</b> <span class="mono">SA14-310/POD28iss1.ERR</span> is a design-rule report for a POD-28, not for this card.`,
  `<b>Spelling on the schematic.</b> One diode is labelled “IN4148” (letter I) next to its three “1N4148” siblings; the M8205B8 last-designation note lists “C31, CR6, Q8, R59 & U4”.`,
  `<b>A short can cook a resistor.</b> At the +30 dBm maximum, a shorted M8205B output puts about ${(Math.pow(dBu2V(24)/60,2)*30).toFixed(1)} W into each 30 Ω 1 W build-out before the current limit acts — ${inf} from the schematic values.`,
];
const assume = [
  `Op-amp swing (±16.5 V on ±18 V) and output-leg swing (±20 V on ±22 V) ${inf} from the rails on M8205B8.DWG.`,
  `Current limit ≈ 0.65 V / 2.2 Ω per leg ${inf} from Q4/Q1 2N4401 across R42/R43 2.2 Ω.`,
  `The CMR trim curve (how far R9/C4 must move to reach 80 dB) is ${inf}; the 80 dB figure is the spec.`,
  `Hotspots on the TB8205P come from the guide PDF's text layer; the M8205 uses the same TB8205P as the M8205B.`,
];

